                ${escapeHtml(copy.eyebrow)}
              </p>
            </td>
          </tr>

          <tr>
            <td style="padding:32px 28px 8px;">
              <h1 style="margin:0 0 16px;font-size:22px;line-height:1.25;letter-spacing:-0.03em;font-weight:800;color:${BRAND.ink};">
