async function sendWithResend(opts: {
  to: string;
  subject: string;
  html: string;
}): Promise<{ ok: true; id?: string } | { ok: false; status: number; body: string }> {
  const apiKey = Deno.env.get("RESEND_API_KEY");
  if (!apiKey) throw new Error("RESEND_API_KEY missing");

  const fromEmail = Deno.env.get("AUTH_FROM_EMAIL") || Deno.env.get("FROM_EMAIL") || FROM_EMAIL;
  const replyTo = Deno.env.get("AUTH_REPLY_TO") || REPLY_TO_EMAIL;

  const resp = await fetch("https://api.resend.com/emails", {
    method: "POST",
    headers: {
      Authorization: `Bearer ${apiKey}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      from: `${FROM_NAME} <${fromEmail}>`,
      to: [opts.to],
      reply_to: replyTo,
      subject: opts.subject,
      html: opts.html,
    }),
  });

  const body = await resp.text();
  if (!resp.ok) return { ok: false, status: resp.status, body };
  try {
    const parsed = JSON.parse(body) as { id?: string };
    return { ok: true, id: parsed.id };
  } catch {
    return { ok: true };
  }
}

Deno.serve(async (req) => {
  try {
    const HOOK_SECRET = Deno.env.get("SEND_EMAIL_HOOK_SECRET");
    if (!HOOK_SECRET) throw new Error("SEND_EMAIL_HOOK_SECRET missing");
    if (!Deno.env.get("RESEND_API_KEY")) throw new Error("RESEND_API_KEY missing");

    const payload = await req.text();
    const headers = Object.fromEntries(req.headers as unknown as Iterable<[string, string]>);

    const secret = HOOK_SECRET.replace(/^v1,whsec_/, "");
    const wh = new Webhook(secret);
    const data = wh.verify(payload, headers) as {
      user: { email: string; user_metadata?: Record<string, unknown> };
      email_data: {
        token: string;
        token_hash: string;
        redirect_to: string;
        email_action_type: string;
        site_url: string;
        token_new?: string;
        token_hash_new?: string;
      };
    };

    const { user, email_data } = data;

    const PUBLIC_APP_URL = Deno.env.get("PUBLIC_APP_URL") || "https://www.vetocrm.com";
    const incoming_redirect = email_data.redirect_to || "";
    const safe_redirect =
      incoming_redirect && !/lovable\.(dev|app)\/(login|auth-bridge)/.test(incoming_redirect)
        ? incoming_redirect
        : PUBLIC_APP_URL;

    const lang = resolveLang({
      userMeta: user.user_metadata,
      redirectTo: safe_redirect,
    });

    const confirmation_url = `${email_data.site_url}/auth/v1/verify?token=${email_data.token_hash}&type=${email_data.email_action_type}&redirect_to=${encodeURIComponent(safe_redirect)}`;

    const { subject, html } = renderEmail({
      lang,
      user_email: user.email,
      confirmation_url,
      token: email_data.token,
      email_action_type: email_data.email_action_type,
    });

    const result = await sendWithResend({ to: user.email, subject, html });
    if (!result.ok) {
      console.error("Resend send failed", result.status, result.body);
      return new Response(
        JSON.stringify({
          error: { http_code: 502, message: `Resend send failed: ${result.body}` },
        }),
        { status: 200, headers: { "Content-Type": "application/json" } },
      );
    }

    return new Response(JSON.stringify({}), {
      status: 200,
      headers: { "Content-Type": "application/json" },
    });
  } catch (e) {
    console.error("auth-email-hook error", e);
    return new Response(
      JSON.stringify({ error: { http_code: 401, message: String((e as Error).message || e) } }),
      { status: 200, headers: { "Content-Type": "application/json" } },
    );
  }
});
